from pathlib import Path
import json,sys
state=Path('/root/.local/state/rust-full-migration-20261028-lu443ytp/artifacts')
baseline=state/'json-document-benchmark/round1'
revised=Path(sys.argv[1])
reports=[json.loads((directory/f'lossless-json-document-benchmark-{runtime}.json').read_text()) for directory,runtime in [(revised,'node'),(baseline,'rust'),(revised,'rust')]]
labels={'small-strings':'Small / missing / falsy values','wide-object':'Wide object and duplicate keys','large-ignored':'8 KiB ignored payload','deep-selected':'Selected value: 256 nested arrays','escaped-strings':'Escapes and lone UTF-16 surrogates'}
data=[]
for index,w in enumerate(reports[0]['workloads']):
 rows=[]
 for report in reports:
  row=report['workloads'][index];assert row['name']==w['name'];rows.append({'median':row['medianNsPerOp']/1000,'min':min(x['nsPerOp'] for x in row['samples'])/1000,'max':max(x['nsPerOp'] for x in row['samples'])/1000})
 data.append({'name':labels[w['name']],'rows':rows})
html='''<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground);font:14px var(--font-sans,system-ui)}h3{font-size:18px;margin:0 0 8px}p{color:var(--muted-foreground);line-height:1.5;margin:8px 0}select{width:100%;padding:10px;color:var(--foreground);background:var(--card);border:1px solid var(--border);border-radius:var(--radius,8px);font:inherit;margin:10px 0}svg{display:block;width:100%;height:250px}text{fill:var(--foreground);font:13px var(--font-sans,system-ui)}.muted{fill:var(--muted-foreground)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px 5px;text-align:right;border-bottom:1px solid var(--border)}th:first-child,td:first-child{text-align:left}th{color:var(--muted-foreground);font-weight:500}.scroll{overflow-x:auto}.note{font-size:12px}.metric{color:var(--foreground);font-weight:600}
</style></head><body><h3>Shared JSON operation: measured latency</h3><p>Parse → select error → canonical JSON. Lower is faster. Bars show medians; whiskers show the range of seven samples.</p><select id="workload" aria-label="Choose benchmark workload"></select><svg id="plot" viewBox="0 0 660 250" role="img" aria-label="Node and Rust benchmark latency"></svg><p id="finding" class="metric"></p><div class="scroll"><table><thead><tr><th>Workload</th><th>Node</th><th>Rust before</th><th>Rust revised</th></tr></thead><tbody id="rows"></tbody></table></div><p class="note">Times in µs per operation. Latest confirmation (Rust then Node); all earlier samples are retained. Identical 32-case pools, 20 warmup passes, seven trials. Sequential runs on the same shared host, each capped at 6 CPUs and 4 GiB with no swap. This measures a prepared JSON operation; network, owned subtree copying and whole-application latency are outside its scope.</p><script>
const data=__DATA__,names=['Node rerun','Rust before','Rust revised'],colors=['var(--chart-1)','var(--chart-3)','var(--chart-2)'];
const select=document.getElementById('workload'),svg=document.getElementById('plot'),fmt=n=>n.toFixed(n<1?3:2);
for(let i=0;i<data.length;i++){const option=document.createElement('option');option.value=i;option.textContent=data[i].name;select.append(option);const row=document.createElement('tr');row.innerHTML='<td>'+data[i].name+'</td>'+data[i].rows.map(v=>'<td>'+fmt(v.median)+'</td>').join('');document.getElementById('rows').append(row)}
function draw(){const d=data[Number(select.value)],width=svg.clientWidth||660,left=100,scale=Math.max(65,width-left-95)/Math.max(...d.rows.map(v=>v.max));svg.setAttribute('viewBox','0 0 '+width+' 250');svg.innerHTML='';const NS='http://www.w3.org/2000/svg';function el(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;svg.append(e);return e}for(let i=0;i<3;i++){const y=25+i*75,v=d.rows[i];el('text',{x:4,y:y+15},names[i]);el('rect',{x:left,y:y,width:v.median*scale,height:24,rx:3,fill:colors[i]});el('line',{x1:left+v.min*scale,x2:left+v.max*scale,y1:y+12,y2:y+12,stroke:'var(--foreground)','stroke-width':1.5});for(const x of [v.min,v.max])el('line',{x1:left+x*scale,x2:left+x*scale,y1:y+6,y2:y+18,stroke:'var(--foreground)'});el('text',{x:width-85,y:y+16},fmt(v.median)+' µs');el('text',{x:left,y:y+45,class:'muted'},'range '+fmt(v.min)+'–'+fmt(v.max)+' µs')}const ratio=d.rows[0].median/d.rows[2].median,improvement=d.rows[1].median/d.rows[2].median;document.getElementById('finding').textContent=(ratio>=1?'Revised Rust median is '+ratio.toFixed(2)+'× faster than Node.':'Revised Rust median takes '+(1/ratio).toFixed(2)+'× Node time.')+' Before/revised ratio: '+improvement.toFixed(2)+'×.'}select.onchange=draw;window.addEventListener('resize',draw);draw();
</script></body></html>'''.replace('__DATA__',json.dumps(data))
out=Path('/root/saas-rust/artifacts/json-document-benchmarks.html');out.parent.mkdir(exist_ok=True);out.write_text(html);print(out)
